"""Computer Science (CS) depth, units 1–9 (Nov 2026): two question types for every objective that had none, a second
for every objective that had one. Traces are recomputed by tests/verify/csalgo.py (cs_* helpers written apart from
the hand-worked keys), code by progcode.py (py_out, sh_out for git), arithmetic by sympy; concept picks are authored."""
from opl_dsl import Q

FILE, FRAMEWORK = "cs-depth-1", "computer-science"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
DM, AN, ST, GR, TH, SY, SW = "cs.discrete", "cs.analysis", "cs.structures", "cs.graphs", "cs.theory", "cs.systems", "cs.software"
CODE = {"type": "code", "src": "code"}


def facts(name, skill, rows, explain, pace="quick"):
    return Q(name, skill, "{{q}}", pace=pace, cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


def picks(name, skill, prompt, cases, fn, explain, figure=None):
    """o1 is the hand-worked answer; the verifier recomputes it with fn (an expression) and finds it among the options"""
    return Q(name, skill, prompt, cases=cases, choice=MC, correct="0", verify=f"pick({fn}, [o1, o2, o3, o4])",
             explain=explain, figure=figure)


