# answers precomputed here and checked by the verifier's own helpers
_HUFF = {"45 13 12 16 9 5": 224, "5 9 12 13 16 45": 224, "1 1 2 4": 14, "10 10 10 10": 80, "50 25 15 10": 175}
_CH = {"u=rwx,g=rx,o=": 750, "u=rw,g=r,o=r": 644, "u=rwx,g=rwx,o=rx": 775, "u=rw,g=,o=": 600, "u=rx,g=x,o=x": 511}
_GIT = {"git merge --no-ff feat -m m": 6, "git rebase main": 5, "git merge --squash feat; git commit -m s": 4,
        "git cherry-pick f2": 4, "git revert HEAD --no-edit": 4, "git reset --hard HEAD~1": 2}
for code, q in ADD:
    if q.name == "cs-huffman-avg":
        for c in q.cases:
            fs = [int(t) for t in c["f"].split()]
            c["ans"] = round(_HUFF[c["f"]] / sum(fs), 6); c["tot"] = sum(fs)
    if q.name == "cs-chmod-octal":
        for c in q.cases: c["ans"] = _CH[c["s"]]
    if q.name == "cs-git-count":
        for c in q.cases: c["n"] = _GIT[c["cmd"]]
        q.value = "n"
    if q.name == "cs-semaphore":
        for c in q.cases: c["ans"] = c["s0"] - c["ops"].split().count("P") + c["ops"].split().count("V")
        q.value, q.let = "ans", None
